{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01","C05","C08","C07","C12","C18","C24","C56","C58","C51","C54","C68","C60","C61"],
  "contradictory_card_ids": ["C22","C16"],
  "prediction_basis_card_ids": ["C01","C05","C08","C07","C12","C18","C24","C56","C58","C51","C54","C68","C60"],
  "claims": [
    {
      "claim": "Direct human absolute-bioavailability measurements in the most transferable contexts are all above the 20% threshold: imidafenacin 57.8%, tolvaptan 56%, ACT-1004-1239 53%, bromazepam 86%, and lenvatinib ~85%; venadaparib, a benzamide/indazole context structurally closest to the query, is reported as good and 70.63% in mice.",
      "card_ids": ["C01","C05","C08","C07","C12","C18","C24"]
    },
    {
      "claim": "L4 absorption records show that low aqueous solubility does not by itself preclude F >= 20%: piroxicam has fa ~100% and negligible first-pass metabolism despite water solubility of only 14.27 µg/mL.",
      "card_ids": ["C56","C58","C51","C54","C48"]
    },
    {
      "claim": "L5 Caco-2 records for heteroaromatic amides/indazoles show high permeability and generally low efflux (e.g., indazole carboxamide Papp 33.1×10^-6 cm/s; high-permeability compounds with efflux ratio <2), supporting absorption without strong gut-wall efflux; these are mechanistic, not direct F measurements.",
      "card_ids": ["C68","C60","C61","C64"]
    },
    {
      "claim": "The only affirmative low-F evidence (apatinib L2 10-20% and ilomastat 'not good') is low-transferability and conflicts with L1 labels; it does not affirmatively establish F < 20% for the query.",
      "card_ids": ["C22","C16"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability value for the query molecule.",
    "No query-specific fasted-state solubility, dissolution, permeability, gut-wall efflux, or intestinal metabolism data.",
    "L5 records are for other molecules and mostly report Caco-2 permeability/efflux, not systemic F or intestinal metabolism.",
    "L3 oral AUC/Cmax records lack IV comparators, so they cannot quantify F or confirm the F >= 20% threshold.",
    "Apatinib L2 low value lacks species, dose, formulation, and comparator detail and conflicts with its L1 'good' label.",
    "Most context records are not explicitly fasted; tolvaptan food independence and ARRY-403 fasted data only partially address this."
  ],
  "decision_summary": "Predicted high: F >= 20% remains better supported by multiple transferable direct human absolute-bioavailability contexts, especially the benzamide/indazole and lipophilic benzamide scaffolds (venadaparib, tolvaptan, imidafenacin, ACT-1004-1239, bromazepam, lenvatinib), reinforced by L2 preclinical values above 20% and by L4/L5 absorption/permeability evidence (piroxicam fa ~100% despite low solubility; high Caco-2 permeability with low efflux). The new L5 gut-wall efflux/intestinal-metabolism records are supportive for absorption but not direct F evidence and do not change the decision. Apatinib's conflicting 10-20% L2 value and ilomastat's poor-F context are low-transferability and do not overturn. Solubility/lipophilicity and lack of query-specific first-pass data remain uncertainties, not affirmative evidence for F < 20%."
}

